return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=3; plural=(n==0 ? 0 : n%10==1 && n%100!=11 ? 1 : 2);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Pārejiet uz spraudņa meklēšana','Activate %s' => 'Aktivizēt %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> ir jāinstalē un jāaktivizē <strong>%2$s</strong>. <a href="%4$s">%3$s</a>','Enter your code here' => 'Ievadiet savu kodu šeit','Add %s' => 'Pievienot %s','Remove' => 'Noņemt','Order number and receipt will be sent to this email address.' => 'Pasūtījuma numurs un kvīts tiks nosūtīti uz šo e-pasta adresi.','Apartment, unit, building, floor, etc.' => 'Dzīvoklis, vienība, ēka, stāvs utt.','Shipping phone' => 'Piegādes tālrunis','Only used for shipping-related questions.' => 'Izmanto tikai ar nosūtīšanu saistītiem jautājumiem.','Single step' => 'Viens solis','Click to go to the order summary' => 'Noklikšķiniet, lai pārietu uz pasūtījuma kopsavilkumu','Cart total:' => 'Kopējais grozs:','Proceed to %s' => 'Pārejiet uz %s','Proceed to contact' => 'Turpiniet sazināties ar','Proceed to shipping' => 'Pārejiet uz nosūtīšanu','Proceed to billing' => 'Pārejiet uz rēķinu izrakstīšanu','Proceed to payment' => 'Pārejiet uz maksājumu','Shipping method' => 'Piegādes metode','Additional notes' => 'Papildu piezīmes','Payment method' => 'Maksājuma metode','Step %1$s of %2$s' => '%1$s solis no %2$s','Change: %s' => 'Izmaiņas: %s','Not selected yet.' => 'Vēl nav izvēlēts.','Same as shipping address' => 'Tāda pati kā piegādes adrese','Same as billing address' => 'Tāda pati kā norēķinu adrese','Order summary' => 'Pasūtījuma kopsavilkums','Edit cart' => 'Rediģēt grozs','Did you mean %s?' => 'Vai jūs domājāt %s?','Change email address to: {suggestion-value}' => 'Mainīt e-pasta adresi uz: {priekšlikums-vērtība}','This is a required field.' => 'Šis ir obligāts lauks.','This is not a valid email address.' => 'Šī nav derīga e-pasta adrese.','This field does not match the related field value.' => 'Šis lauks neatbilst saistītā lauka vērtībai.','The CPF number "{cpf_number}" is invalid.' => 'CPF numurs "{cpf_number}" ir nederīgs.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ numurs "{cnpj_number}" ir nederīgs.','(Required)' => '(Obligāti)','Checkout Header - Desktop' => 'Kases galvene - darbvirsma','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Rīkrīku rādīšana kases galvenē lielos ekrānos. Tiek rādīts tikai tad, ja tiek izmantota spraudņa kases galvene.','Checkout Header - Mobile' => 'Checkout Header - Mobilais','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Rīkrīku rādīšana zem kases galvenes mobilajām ierīcēm. Tiek rādīts tikai tad, ja tiek izmantota spraudņa kases galvene.','Checkout Sidebar' => 'Kases sānu josla','Display widgets on the checkout sidebar after the order summary.' => 'Rīknes rādīšana izrakstīšanās sānjoslā pēc pasūtījuma kopsavilkuma.','Checkout Order Summary' => 'Kases pasūtījuma kopsavilkums','Display widgets inside the order summary at the checkout page.' => 'Rīkrīku rādīšana pasūtījuma kopsavilkuma iekšpusē izrakstīšanās lapā.','Checkout Below Place Order' => 'Checkout Zemāk Vieta pasūtījumam','Display widgets below the place order button at the checkout page.' => 'Rīknes rādīšana zem pasūtījuma veikšanas pogas izrakstīšanās lapā.','Checkout Footer' => 'Checkout Footer','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Rīknes logrīku rādīšana kases pēdiņā. Tiek rādīts tikai tad, ja tiek izmantota spraudņa kases pēdiņa.','Classic' => 'Classic','Boxed' => 'Iepakojumā','Split' => 'Split','Minimalist' => 'Minimālisma','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'CodeRockz izstrādātie šķidruma izrakstīšanās un piegādes datuma spraudņi','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Mēs atklājām, ka jūs izmantojat CodeRockz spraudņus Delivery & Pickup Date Time for WooCommerce (bezmaksas un PRO). Integrācija ar šiem spraudņiem ir pārcelta uz Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Upgrade uz PRO','Fluid Checkout database updated successfully' => 'Veiksmīgi atjaunināta Fluid Checkout datubāze','The database changes where applied successfully.' => 'Datubāzes izmaiņas tika piemērotas veiksmīgi.','Dismiss' => 'Atbrīvot','Fluid Checkout database update' => 'Fluid Checkout datubāzes atjaunināšana','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Datu bāzē ir jāveic dažas izmaiņas. Tāpat kā jebkura atjauninājuma gadījumā, mēs iesakām pirms tā veikšanas <strong>izveidot pilnu vietnes dublējumu</strong>.','Update database' => 'Atjaunināt datubāzi','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout nav saderīgs ar Divi Builder izrakstīšanās izkārtojumu','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Plūdenai kasei ir nepieciešama klasiskā WooCommerce kases veidlapa, kas balstīta uz īsajiem kodiem, lai tā darbotos. Izmantojot Divi Builder, lai pielāgotu kases lapas izskatu, klasiskās īsās kodes tiek aizstātas ar pielāgotiem logrīkiem no Divi Builder katrai kases lapas daļai. Šie pielāgotie logrīki nav saderīgi ar Fluid Checkout.</p><p>Lūdzu rediģējiet savu kases lapu, aizstājot Divi Builder logrīkus ar teksta logrīku, kas satur īsceļu kodu <code>[woocommerce_checkout]</code>.</p>','Edit the checkout page' => 'Izrakstīšanās lapas rediģēšana','Read the documentation.' => 'Izlasiet dokumentāciju.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Izmantojot Fluid Checkout, jādeaktivizē PRO daudzpakāpju izrakstīšanās funkcija','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Izmantojot Fluid Checkout, daudzpakāpju funkcija no Germanized PRO spraudņa kļūst nevajadzīga un var radīt <strong>kritiskas kļūdas jaunu pasūtījumu apstrādes laikā</strong>. Lūdzu, atspējojiet Germanized PRO daudzpakāpju kases funkciju spraudņa iestatījumos.','Go to Germanized settings' => 'Pārejiet uz vāciski iestatījumiem','Thanks for choosing Fluid Checkout!' => 'Paldies, ka izvēlējāties Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Jūs jau kādu laiku izmantojat spraudni. Kā jums tas līdz šim patīk? <br>Lūdzu, dodiet mums ātru novērtējumu, mēs novērtējam katru atsauksmi, un tas mūs mudina turpināt uzlabot spraudni :)','Rate the plugin' => 'Novērtējiet spraudni','I need help!' => 'Man vajadzīga palīdzība!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Dažas WooCommerce Checkout Manager funkcijas, ko Quadlayers var nedarboties, kā gaidīts, ja lietojat to ar Fluid Checkout. Lasiet <a href="%s">mūsu dokumentāciju</a>, lai iegūtu vairāk informācijas un alternatīvus risinājumus.','Read documentation' => 'Lasīt dokumentāciju','Don\'t show this again' => 'Neparādiet to vēlreiz','Fluid Checkout PRO' => 'Šķidruma pārbaude PRO','More design templates' => 'Vairāk dizaina veidņu','Optimized cart page' => 'Optimizēta grozs lapa','Optimized order received / thank you page' => 'Optimizēta pasūtījuma saņemšanas / pateicības lapa','Edit cart contents at checkout page' => 'Grozījuma satura rediģēšana izrakstīšanās lapā','Account matching / user matching' => 'Kontu saskaņošana / lietotāju saskaņošana','Trust symbols on the cart and thank you pages' => 'Uzticības simboli grozā un pateicības lapās','More positions for the coupon code on the checkout page' => 'Vairāk pozīciju kupona kods izrakstīšanās lapā','International phone numbers' => 'Starptautiskie tālruņa numuri','Gift messages and packing slips' => 'Dāvanu sūtījumi un iesaiņojuma lapas','Local pickup and in-store collection' => 'Vietējā saņemšana un savākšana veikalā','EU-VAT Assistant' => 'ES PVN maksātāja palīgs','I already have it – Hide this offer' => 'Man jau ir - Paslēpt šo piedāvājumu','Activated' => 'Aktivēts','Address book' => 'Adrešu grāmata','Select an image' => 'Atlasiet attēlu','Cart layout' => 'Groziņa izkārtojums','Cart optimizations' => 'Groziņa optimizācija','Enable cart page optimizations' => 'Iespēja optimizēt grozu lapu','Header and footer template' => 'Virsraksta un kājenes veidne','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Kontrolē, vai izmantot lappuses galveni un apakšējo daļu, kas novērš uzmanību, vai saglabāt pašreiz aktīvās tēmas galveni un apakšējo daļu.','Distraction free header and footer' => 'Virsraksts un pēdiņa, kas novērš uzmanību','Theme\'s header and footer' => 'Tēmas galvene un kājenes','Cart elements' => 'Groziņa elementi','Make the order summary stay visible on the cart page while scrolling' => 'Pasūtījuma kopsavilkuma saglabāšana redzamā vietā grozā ritināšanas laikā','Coupon codes' => 'Kuponu kodi','Hidden' => 'Slēptais','Before the cart items section' => 'Pirms grozā esošo preču sadaļas','Inside the cart items section' => 'Sadaļā "Grozā esošās preces','After the cart items section' => 'Pēc sadaļas ar grozā esošajiem priekšmetiem','Before the shipping section' => 'Pirms nosūtīšanas sadaļas','After the shipping section' => 'Pēc nosūtīšanas sadaļas','Before the order summary' => 'Pirms pasūtījuma kopsavilkuma','Inside the order summary' => 'Pasūtījuma kopsavilkuma iekšpusē','Before the order totals' => 'Pirms pasūtījuma kopsummas','After the order totals' => 'Pēc pasūtījuma kopsummas','After the order summary' => 'Pēc pasūtījuma kopsavilkuma','Shipping' => 'Piegāde','Select position where to display the shipping costs and calculator on the cart page.' => 'Izvēlieties pozīciju, kurā grozu lapā parādīt piegādes izmaksas un kalkulatoru.','Display as a cart section' => 'Rādīt kā grozu sadaļu','Cross-sells' => 'Savstarpējie pārdevumi','Select position where to display the cross-sells section on the cart page.' => 'Izvēlieties pozīciju, kurā tiek parādīta krustojuma pārdošanas sadaļa grozā.','Before the cart actions' => 'Pirms ratiņu darbībām','After the cart actions' => 'Pēc grozā veiktajām darbībām','Layout of cross-sell items on the cart page.' => 'Šķērseniskās pārdošanas elementu izkārtojums grozā.','Optimized horizontal cross-sells layout' => 'Optimizēts horizontālo šķērspārdošanu izkārtojums','Theme\'s cross-sells layout' => 'Tēmas savstarpējās pārdošanas izkārtojums','Number of cross-sell items to display on the cart page' => 'Savstarpējās pārdošanas vienību skaits, kas tiek parādīts grozā lapā','Add widget areas to the cart page' => 'Rīknes laukumu pievienošana grozs lapai','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Šīs logrīku zonas tiek izmantotas, lai pievienotu uzticības simbolus un uzticības nozīmītes grozu lapā.','Checkout' => 'Izrakstīšanās no','Checkout layout' => 'Checkout izkārtojums','Design template' => 'Dizaina veidne','Dark mode' => 'Tumšais režīms','Enable dark mode' => 'Ieslēgt tumšo režīmu','Logo image' => 'Logotipa attēls','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Izvēlieties attēlu, kas tiks rādīts kases lapas galvenē. Attiecas tikai tad, ja tiek izmantots no uzmanības novēršanas brīvs header un footer.','Header background color' => 'Virsraksta fona krāsa','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Izvēlieties fona krāsu kases lapas galvenei. Attiecas tikai tad, ja tiek izmantots no uzmanības novēršanas brīvs header un footer.','HTML color value. ie: #f3f3f3' => 'HTML krāsas vērtība. ti: #f3f3f3f3','Page background color' => 'Lapas fona krāsa','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Izvēlieties fona krāsu kases lapai. Krāsa tiek piemērota elementam <em>body</em>.','Footer background color' => 'Footer fona krāsa','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Izvēlieties fona krāsu izrakstīšanās lapas pēdiņai. Attiecas tikai tad, ja tiek izmantota no uzmanības novēršanas atbrīvota galvene un apakšējā daļa.','Progress bar' => 'Progresa josla','Display the checkout progress bar when using multi-step checkout layout' => 'Rādīt izrakstīšanās progresa joslu, ja tiek izmantots vairāku soļu izkārtojums','Make the checkout progress bar stay visible while scrolling' => 'Nodrošināt, lai izrakstīšanās progresa josla būtu redzama ritināšanas laikā','Express checkout' => 'Ekspress izrakstīšanās','Enable the express checkout section' => 'Ieslēgt ekspress izrakstīšanās sadaļu','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Rāda ekspress izrakstīšanās sadaļu izrakstīšanās laikā, ja atbalstītajiem maksājumu vārtejiem šī funkcija ir iespējota.','Display express checkout buttons in one line for larger screens' => 'Rādīt ekspress izrakstīšanās pogas vienā rindā lielākiem ekrāniem','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Ignorēt papildu kases obligātos laukus, ja maksājums tiek veikts, izmantojot saderīgu ātrās kases maksājumu vārteju.','Make the order summary stay visible while scrolling' => 'Pasūtījuma kopsavilkums paliek redzams ritināšanas laikā','Choose a background color for the order summary section.' => 'Izvēlieties pasūtījuma kopsavilkuma sadaļas fona krāsu.','Highlight the order totals row in the order summary table' => 'Pasvītrot pasūtījuma kopsummas rindu pasūtījuma kopsavilkuma tabulā','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Visnoderīgākais, ja pasūtījuma kopsavilkuma sadaļai nav izceltas fona krāsas. Var arī attiekties uz grozu, saņemto pasūtījumu un pasūtījuma skatīšanas lapām, ja izmantojat Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Rīcības saite pasūtījuma kopsavilkumā pie kases.','Edit cart link' => 'Rediģēt grozs saiti','Cart items count' => 'Grozā esošo vienību skaits','Link to shop page' => 'Saite uz veikala lapu','Cart items' => 'Grozā esošās preces','Hide cart items errors at the checkout page' => 'Paslēpt grozā esošās kļūdas izrakstīšanās lapā','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Izrakstīšanās lapas augšpusē nerādiet ziņu par grozā esošo preču kļūdām. Nosūtot kases veidlapu, lai pabeigtu pirkumu, šie kļūdu ziņojumi tiks rādīti vienmēr.','Place order' => 'Veiciet pasūtījumu','Define the position to display "Place order" and terms checkbox section.' => 'Definēt pozīciju, kurā tiek parādīta sadaļa "Place order" un nosacījumi izvēles rūtiņas sadaļā.','Some options might not be compatible with some plugins and themes.' => 'Dažas opcijas var nebūt saderīgas ar dažiem spraudņiem un tēmām.','Below the payment section' => 'Zem maksājumu sadaļas','Below the order summary' => 'Zem pasūtījuma kopsavilkuma','Both below the payment section and the order summary' => 'Gan zem maksājuma sadaļas, gan pasūtījuma kopsavilkuma','Add widget areas to the checkout page' => 'Rīkloku apgabalu pievienošana izrakstīšanās lapai','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Šīs logrīku zonas tiek izmantotas, lai pievienotu uzticības simbolus un uzticības nozīmītes izrakstīšanās lapā.','Display the coupon codes section title' => 'Rādīt kuponu kodu sadaļas virsrakstu','Select position where to display the coupon codes section on the checkout page.' => 'Izvēlieties pozīciju, kur parādīt kuponu kodu sadaļu izrakstīšanās lapā.','Before the checkout steps' => 'Pirms izrakstīšanās soļiem','As a substep before payment methods' => 'Kā pakāpiens pirms maksājumu metodēm','As a substep after payment methods' => 'Kā pakāpiens pēc maksājumu metodēm','Default button style' => 'Noklusējuma pogas stils','"Add" link button' => '"Pievienot" saites poga','Checkout fields' => 'Izrakstīšanās lauki','Optional fields' => 'Neobligātie lauki','Hide optional fields behind a link button' => 'Neobligāto lauku slēpšana aiz saites pogas','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Ieteicams atstāt šo opciju atzīmētu, lai samazinātu atvērto ievades lauku skaitu, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">lasiet pētījumu</a>.','Do not hide "Address line 2" fields behind a link button' => 'Neslēpiet "Adreses 2. rindas" laukus aiz saites pogas.','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Ieteicams tikai tad, ja lielākajai daļai klientu patiešām ir nepieciešams lauks "Adreses 2. rinda" vai ja ir ļoti svarīgi norādīt pareizo piegādes adresi (piemēram, ja piegādājat pārtiku un citus ātri bojājošos produktus).','Billing address' => 'Norēķinu adrese','Select position where to display the billing address section on the checkout page.' => 'Izvēlieties pozīciju, kurā izrakstīšanas lapas sadaļā parādīt norēķinu adreses sadaļu.','As a step before shipping' => 'Kā posms pirms nosūtīšanas','As a sub-step before the shipping address section' => 'Kā apakšposms pirms piegādes adreses sadaļas','As a sub-step after the shipping address section' => 'Kā apakšposms pēc piegādes adreses sadaļas','As a step after shipping' => 'Kā posms pēc nosūtīšanas','As a sub-step before the payment section' => 'Kā apakšposms pirms maksājuma sadaļas','Force billing and shipping addresses to the same (single section)' => 'Piespiedu norēķinu un piegādes adreses uz vienu un to pašu (viena sadaļa).','Checkbox for "Same as shipping/billing address" checked by default' => 'Pēc noklusējuma atzīmēta izvēles rūtiņa "Tāda pati kā piegādes/norēķinu adrese".','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Pēc noklusējuma izvēles rūtiņa "Tāda pati kā nosūtīšanas adrese" tiks atzīmēta, kad vispirms tiks parādīta nosūtīšanas adreses sadaļa. <br>Grāmatiņa "Same as billing address" (Tāda pati kā rēķina adrese) pēc noklusējuma tiks atzīmēta, kad vispirms tiks parādīta rēķina adreses sadaļa. <br> Ieteicams atstāt šo opciju atzīmētu, lai ievērojami samazinātu atvērto ievades lauku skaitu pie kases, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">lasiet pētījumu</a>.','Highlight the billing address section in the checkout form' => 'Izceliet norēķinu adreses sadaļu izrakstīšanās veidlapā.','Shipping address' => 'Piegādes adrese','Highlight the shipping address section in the checkout form' => 'Izceliet piegādes adreses sadaļu kases veidlapā','Shipping methods' => 'Piegādes metodes','Choose in which position to display the shipping methods section.' => 'Izvēlieties, kurā pozīcijā parādīt piegādes metožu sadaļu.','Before shipping address' => 'Pirms nosūtīšanas adrese','After shipping address' => 'Pēc nosūtīšanas adreses','Local pickup' => 'Vietējā savākšana','Removes shipping address section when a local pickup shipping method is selected.' => 'Noņem piegādes adreses sadaļu, ja ir izvēlēta vietējās saņemšanas piegādes metode.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Aizstāj piegādes adresi ar saņemšanas vietas atrašanās vietu, ja ir izvēlēta vietējā saņemšanas metode.','Choose which address to save as the shipping address for local pickup orders.' => 'Izvēlieties, kuru adresi saglabāt kā piegādes adresi vietējās saņemšanas pasūtījumiem.','Save the selected pickup location' => 'Saglabāt izvēlēto paņemšanas vietu','Save same as the billing address' => 'Saglabāt to pašu kā norēķinu adresi','Do not save any shipping address' => 'Nesaglabājiet nevienu piegādes adresi','Company name field for shipping address' => 'Uzņēmuma nosaukuma lauks piegādes adresei','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Mainiet uzņēmuma nosaukuma lauka redzamību izrakstīšanās adreses sadaļā izrakstīšanās veidlapas sadaļā.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Ja lauks ir iestatīts kā "izvēles", kas ir noklusējuma redzamības stāvoklis, netiks piemērotas nekādas izmaiņas, lai citi spraudņi varētu piemērot nepieciešamās izmaiņas.','Hidden (remove field)' => 'Slēptas (noņemt lauku)','Optional' => 'Pēc izvēles','Required' => 'Nepieciešams','Add shipping phone field to the checkout form.' => 'Piegādes tālruņa lauka pievienošana izrakstīšanās veidlapai.','Choose in which step to display the shipping phone field.' => 'Izvēlieties, kurā solī parādīt nosūtīšanas tālruņa lauku.','Contact step' => 'Kontakta solis','Billing phone' => 'Norēķinu tālrunis','Add billing phone field to the checkout form.' => 'Pievienojiet norēķinu tālruņa lauku izrakstīšanās veidlapai.','Choose in which step to display the billing phone field.' => 'Izvēlieties, kurā solī parādīt norēķinu tālruņa lauku.','Show country code beside the flag' => 'Rādīt valsts kodu blakus karogam','Show an example of a valid phone number inside phone fields' => 'Parādiet derīga tālruņa numura piemēru tālruņa lauku iekšpusē','Do not change placeholders' => 'Nemainiet vietzīmes','Show if not defined' => 'Rādīt, ja nav definēts','Always show' => 'Vienmēr parādiet','Order notes' => 'Pasūtījuma piezīmes','Define the visibility of the additional order notes field.' => 'Nosakiet papildu pasūtījuma piezīmju lauka redzamību.','Gift options' => 'Dāvanu iespējas','Allow customers to add a gift message and other gift related options to the order.' => 'Ļaujiet klientiem pievienot pasūtījumam dāvanas ziņojumu un citas ar dāvanu saistītas iespējas.','Display the gift message as part of the order details table instead of a separate section' => 'Dāvanu ziņojuma parādīšana kā pasūtījuma informācijas tabulas daļas, nevis atsevišķas sadaļas vietā.','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Šī opcija ietekmē pasūtījuma apstiprinājuma lapu (pateicības lapu) un pasūtījuma informāciju konta lapās, e-pasta vēstulēs un iesaiņojuma lapās.','Account matching' => 'Kontu saskaņošana','Enable the account matching feature' => 'Kontu atbilstības funkcijas ieslēgšana','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Saistīt viesa klienta pasūtījumus ar viņa esošo kontu, ja konts ar klienta kontaktinformāciju jau ir izveidots.','Display message when an account exists with the email address provided' => 'Rādīt ziņojumu, ja ar norādīto e-pasta adresi ir izveidots konts','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Aizstāj konta izveides laukus ar paziņojumu un iespēju pieteikties. Dažos kontekstos šo opciju var būt ieteicams atstāt atspējotu, lai aizsargātu klientu privātumu.','Dashboard' => 'Vadības panelis','Integrations' => 'Integrācija','License keys' => 'Licences atslēgas','Visit our website for more information about our plugins and add-ons.' => 'Apmeklējiet mūsu vietni, lai iegūtu vairāk informācijas par mūsu spraudņiem un papildinājumiem.','Order pay page' => 'Pasūtījuma apmaksas lapa','Order pay' => 'Pasūtījuma apmaksa','Enable order pay page optimizations' => 'Iespēja veikt pasūtījuma apmaksas lapas optimizāciju','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Maina pasūtījumu apmaksas lapas izkārtojumu esošajiem pasūtījumiem, kas gaida klienta maksājumu.','Add widget areas to the order pay page' => 'Rīkojuma apmaksas lapas logrīku pievienošana','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Šīs logrīku zonas tiek izmantotas, lai pasūtījumu apmaksas lapā pievienotu uzticības simbolus un uzticības nozīmītes.','Thank you page & order details layout' => 'Pateicības lapa un pasūtījuma informācijas izkārtojums','Order details optimizations' => 'Pasūtījuma detaļas optimizācija','Enable thank you page and order details optimizations' => 'Iespēja optimizēt pateicības lapu un pasūtījuma informāciju','Changes the layout of order details on the thank you page and account pages.' => 'Mainīts pasūtījuma informācijas izkārtojums pateicības lapā un konta lapās.','Enable order details customizations on email notifications' => 'Iespēja pielāgot pasūtījuma informāciju e-pasta paziņojumos','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Jaunu sadaļu rādīšana un sadaļu secības maiņa e-pasta paziņojumos. Pasūtījuma informācijas stili e-pasta paziņojumos paliek nemainīgi.','Thank you page' => 'Pateicības lapa','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Šīs opcijas ietekmē pateicības lapu, kas pazīstama arī kā pasūtījuma saņemšanas vai pasūtījuma apstiprinājuma lapas.','Order details layout' => 'Pasūtījuma informācijas izkārtojums','Display the order details with wide layout on the thank you page' => 'Parādiet pasūtījuma informāciju ar plašu izkārtojumu pateicības lapā','Add widget areas to the thank you page' => 'Pateicības lapas logrīku pievienošana','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Šīs logrīku zonas tiek izmantotas, lai pateicības lapā pievienotu uzticības simbolus un uzticības nozīmītes.','Order actions' => 'Rīkojuma darbības','Choose in which position to display the order actions.' => 'Izvēlieties, kurā pozīcijā attēlot pasūtījuma darbības.','Inside the order overview' => 'Pasūtījuma pārskats','After the order overview' => 'Pēc pasūtījuma pārskata','After order sections' => 'Pēc pasūtījuma sadaļas','Order status' => 'Pasūtījuma statuss','Display the order status progress bar' => 'Rādīt pasūtījuma statusa progresa joslu','Choose in which position to display the section.' => 'Izvēlieties, kurā pozīcijā parādīt sadaļu.','After the order overview and payment instructions' => 'Pēc pasūtījuma pārskata un maksājuma norādījumiem','Before the order items section' => 'Pirms pasūtījuma elementu sadaļas','Inside the order items section' => 'Sadaļas "Pasūtījuma priekšmeti" iekšpusē','After the order items section' => 'Pēc pasūtījuma elementu sadaļas','On the sidebar' => 'Sānu joslā','Order downloads' => 'Pasūtīt lejupielādes','Gift message' => 'Dāvanu ziņojums','Tools' => 'Instrumenti','Troubleshooting' => 'Problēmu novēršana','Debug options' => 'Dzesēšanas opcijas','Debug mode' => 'Dzesēšanas režīms','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Debug režīma izmantošana ietekmē vietnes veiktspēju. Šo opciju izmantojiet tikai problēmu novēršanas laikā.','Load unminified assets' => 'Iekraut neminizētus aktīvus','Enhanced select fields' => 'Uzlabotie atlases lauki','Fix automatic zoom-in on form fields' => 'Veidlapu lauku automātiskās tālummaiņas labošana','Set <code>font-size</code> inside form fields to 16px' => 'Iestatiet <code>font-size</code> veidlapas laukos uz 16px','Fluid Checkout' => 'Šķidruma pārbaude','Settings' => 'Iestatījumi','Support' => 'Atbalsts','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Atjauniniet uz PRO</a>, lai atslēgtu vairāk iespēju.','(PRO)' => '(PRO)','(experimental)' => '(eksperimentāls)','Please verify your phone number.' => 'Lūdzu, pārbaudiet savu tālruņa numuru.','The Bluehost Plugin' => 'Bluehost spraudnis','Custom fields' => 'Pielāgotie lauki','Enable custom shipping email field' => 'Ieslēgt pielāgotu piegādes e-pasta lauku','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Ja šī iespēja ir iespējota, kases veidlapai tiks pievienots Bluehost spraudņa piegādes e-pasta lauks.','Captcha Pro by BestWebSoft' => 'Captcha Pro by BestWebSoft','Captcha position' => 'Captcha pozīcija','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Definējiet pozīciju, kurā tiks parādīta captcha sadaļa. Dažas pozīcijas var nedarboties atkarībā no izvēlētā captcha tipa.','Selecting a pickup point is required before proceeding.' => 'Pirms turpināšanas ir jāizvēlas savākšanas punkts.','Pickup point' => 'Savākšanas punkts','Pickup point not selected yet.' => 'Vēl nav izvēlēts savākšanas punkts.','Pickup point:' => 'Uzņemšanas vieta:','Mailchimp for WooCommerce' => 'Mailchimp for WooCommerce','Subscribe checkbox' => 'Parakstīšanās izvēles rūtiņa','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Pārraksta abonēšanas izvēles rūtiņas pozīciju izrakstīšanās lapā un vienmēr parāda to kontaktpersonas posmā.','Before Shipping Address' => 'Pirms nosūtīšanas adrese','(originally "%s")' => '(sākotnēji "%s")','After Shipping Address' => 'Pēc nosūtīšanas adrese','Selecting a collection point is required when shipping with FermoPoint.' => 'Nosūtot ar FermoPoint, ir jāizvēlas savākšanas punkts.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Ja ir atzīmēts, informē lietotājus par pārrakstīšanās kļūdām e-pastā. (Šī funkcija ir atspējota, jo Fluid Checkout piedāvā šo funkciju. Šīs opcijas izmaiņas nestāsies spēkā).','Enable Mail Check: (disabled feature)' => 'Ieslēgt pasta pārbaudi: (funkcija ir atspējota)','Carrier:' => 'Pārvadātājs:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce e-pasta mārketings','Sign up checkbox position' => 'Reģistrēties izvēles rūtiņas pozīcija','Move the sign up checkbox to the contact step' => 'Pārceliet reģistrēšanās izvēles rūtiņu uz kontaktu soli.','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Ja šī iespēja ir iespējota, izvēles rūtiņa tiks pārvietota uz kontaktu soli neatkarīgi no displeja atrašanās vietas, kas noteikta Sendinblue spraudņa iestatījumos.','Theme Betheme' => 'Tēma Betēma','Checkout progress' => 'Izrakstīšanās progress','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Izvadiet izrakstīšanas soļu sadaļu no Betheme izrakstīšanās, grozā un saņemtā pasūtījuma lapās.','Theme Fennik' => 'Tēma Fennik','Breadcrumbs' => 'Maizes drupatas','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Izvadiet sadaļu "Maizes drupatas" no Fennik tēmas, kad izmantojat Fluid Checkout galveni un kājenes.','Theme Go' => 'Tēma Go','My account layout' => 'Mana konta izkārtojums','Enable wide layout on "My account" page.' => 'Iespējot plašu izkārtojumu lapā "Mans konts".','Theme Impreza' => 'Tēma Impreza','Header' => 'Virsraksts','Spacing for site header at the checkout page (in pixels)' => 'Attālums starp vietnes galveni izrakstīšanās lapā (pikseļos)','Only applicable when using the Impreza theme header at the checkout page.' => 'Piemērojams tikai tad, ja kases lapā tiek izmantota Impreza tēmas galvene.','Theme Kapee' => 'Tēma Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Izvadiet Kapee tēmas izrakstīšanas soļu sadaļu no Kapee tēmas izrakstīšanas, groza un saņemtā pasūtījuma lapās.','Theme Porto' => 'Tēma Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Izvadiet izrakstīšanas soļu sadaļu no Porto tēmas izrakstīšanas, groza un saņemtā pasūtījuma lapās.','Theme Pressmart' => 'Tēma Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Izvadiet izrakstīšanas soļu sadaļu no Pressmart tēmas izrakstīšanas, groza un saņemtā pasūtījuma lapās.','Theme The Gem' => 'Tēma Dārgakmens','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Izvadiet kases soļu sadaļu no The Gem tēmas, kad izmantojat Fluid Checkout galveni un kājenes.','Theme Woodmart' => 'Tēma Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Izvadiet izrakstīšanas soļu sadaļu no Woodmart tēmas, kad izmantojat Fluid Checkout galveni un kājenes.','Checkout options' => 'Izrakstīšanās opcijas','Disable the theme checkout options' => 'Atslēgt tēmas izrakstīšanās opcijas','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Pēc noklusējuma ir atspējotas tēmas pievienotās opcijas parādīt produkta attēlu, daudzuma lauks, noņemšanas poga un saite uz produkta lapu.','Theme Atomion' => 'Tēma Atomion','Order progress' => 'Pasūtījuma izpildes gaita','Display order progress from the theme' => 'Rādīt pasūtījuma progresu no tēmas','Display the form field labels visible on the page' => 'Parādīt lapā redzamos formas lauku marķējumus','It is recommended to keep this option enabled for a better user experience.' => 'Ieteicams saglabāt šo opciju ieslēgtu, lai uzlabotu lietotāja pieredzi.','Theme ZK Nito' => 'Tēma ZK Nito','Add extra fields to the checkout form' => 'Papildu lauku pievienošana kases veidlapai','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Pievieno papildu piegādes e-pasta un piegādes tālruņa lauku piegādes adreses sadaļai.','Go to the home page' => 'Dodieties uz sākuma lapu','Skip to content' => 'Pāriet uz saturu','Create an account' => 'Izveidot kontu','Log in to your account' => 'Piesakieties savā kontā','Already have an account?' => 'Jums jau ir konts?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Autorizējies kā %1$s. <a href="%2$s">Atstājies</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Jūsu pasūtījuma kopējā summa ir %s. Papildu maksājums nav nepieciešams.','Close and continue with checkout' => 'Aizveriet un turpiniet izrakstīšanos','Continue' => 'Turpināt','Parcel terminal' => 'Sūtījumu terminālis','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Šis logrīks ir aizstāts ar Fluid Checkout. </p><p>Ja izmantojat Fluid Checkout, lai kases lapa darbotos pareizi, tajā jāizmanto oriģinālais WooCommerce saīsinātais kods <code>[woocommerce_checkout]</code>.</p><p>Lai iegūtu vairāk informācijas, apmeklējiet Fluid Checkout dokumentāciju.</p>','Theme The7' => 'Tēma The7','Additional header sections' => 'Papildu galvenes sadaļas','Output additional header sections if enabled in the theme settings.' => 'Izvadiet papildu galvenes sadaļas, ja tas ir iespējots tēmas iestatījumos.','More information' => 'Vairāk informācijas','Pick a Locker' => 'Izvēlieties skapīti','Page template' => 'Lapas veidne','Use `Order confirmation` page template for block-based themes' => 'Izmantojiet `Pasūtījuma apstiprinājuma` lapas veidni uz blokiem balstītām tēmām','Only applies when using a block-based theme.' => 'Piemēro tikai tad, ja tiek izmantota uz blokiem balstīta tēma.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe vārtejas','Payment form' => 'Maksājuma veidlapa','Apply styles to the Stripe payment form fields' => 'Stilu piemērošana Stripe maksājumu veidlapas laukiem','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Ja šī opcija ir iespējota, Fluid Checkout tiks piemēroti stili, kas optimizēti saderībai ar spraudni. Ja izmantojat pielāgotus stilus Stripe maksājumu veidlapas laukiem, iespējams, vēlēsieties to atspējot.','Theme Nyture' => 'Tēma Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Izvadiet kases soļu sadaļu no Nyture tēmas, kad izmantojat Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Ļauj klientiem veikt maksājumus par pasūtījumiem, kurus veikala administrators ir izveidojis manuāli vai kuri nav pabeigti izrakstīšanās laikā.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Quadlayers spraudnis WooCommerce Checkout Manager nav saderīgs ar Fluid Checkout','Company name field for billing address' => 'Uzņēmuma nosaukuma lauks norēķinu adresei','Change visibility for the company name field for the billing address section on the checkout form.' => 'Mainīt uzņēmuma nosaukuma lauka redzamību norēķinu adreses sadaļā izrakstīšanas veidlapā.','Theme Bookshelf' => 'Tematiskais grāmatu plaukts','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Izvadiet izrakstīšanas soļu sadaļu no Grāmatu plaukta tēmas, kad izmantojat Fluid Checkout.','Account password' => 'Konta parole','An account will be created with the information provided at checkout when completing the order.' => 'Konts tiks izveidots, izmantojot informāciju, kas norādīta pie kases, pabeidzot pasūtījumu.','Choose the style of the progress bar.' => 'Izvēlieties progresa joslas stilu.','Bars' => 'Bāri','Theme Ireca' => 'Tēma Ireca','WooCommerce page layout' => 'WooCommerce lapas izkārtojums','Force wide layout on WooCommerce pages' => 'Izspiest plašu izkārtojumu WooCommerce lapās','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Tas nodrošina, ka satura sadaļa nav pārāk šaura WooCommerce lapās, tostarp izrakstīšanās, grozā, saņemtā pasūtījuma, pasūtījuma apmaksas un konta lapās.','WooCommerce Smart Coupons' => 'WooCommerce viedie kuponi','Position on checkout page' => 'Atrašanās vieta izrakstīšanās lapā','Choose where to display the available coupons section on the checkout page.' => 'Izvēlieties, kur izvietot pieejamo kuponu sadaļu izrakstīšanās lapā.','Before the progress bar' => 'Pirms progresa joslas','After the progress bar' => 'Pēc progresa joslas','Before coupon codes section' => 'Pirms kuponu kodu sadaļas','Format phone numbers according to the rules for each country.' => 'formatējiet tālruņa numurus atbilstoši katras valsts noteikumiem.','Use precise phone number validation' => 'Precīzas tālruņa numura validācijas izmantošana','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Šī ir eksperimentāla funkcija, un tā var nedarboties atbilstoši gaidītajam visos iestatījumos. Izmantojiet to piesardzīgi.','Phone number validation types used when precise validation is enabled.' => 'Tālruņa numura validēšanas veidi, ko izmanto, ja ir iespējota precīza validēšana.','Mobile' => 'Mobilais','Fixed line' => 'Fiksētā līnija','Toll free' => 'Bezmaksas','Or' => 'Vai','Contact' => 'Sazinieties ar','Multi step' => 'Vairāki soļi','2 columns' => '2 kolonnas','1 column' => '1 sleja','Before checkout steps' => 'Pirms izrakstīšanās veicamie soļi','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Izmantojot <em>"1 kolonnas"</em> izkārtojumu, šī opcija vienmēr ir iestatīta uz <em>"Pirms kases soļiem"</em> un attiecas arī uz datora skatu.','Position for the extra order summary section on mobile.' => 'Papildu pasūtījuma kopsavilkuma sadaļas pozīcija mobilajā ierīcē.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Iespēja <em>"Vietnes galvenē"</em> attiecas tikai uz gadījumiem, kad tiek izmantota galvene, kas novērš uzmanību.','On the site header (requires distraction-free header)' => 'Vietnes galvenē (nepieciešama galvene, kas novērš uzmanību)','Initial state for the expansible order summary section on mobile.' => 'Sākotnējais stāvoklis paplašināmā pasūtījuma kopsavilkuma sadaļā mobilajā ierīcē.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Mēs iesakām to iestatīt kā <em>izvērstu</em> šādās valstīs, ņemot vērā normatīvās prasības: <strong>Vācija</strong>, <strong>Austrija</strong>, <strong>Šveice</strong>, <strong>Nīderlande</strong>, <strong>Polija</strong>, <strong>Beļģija</strong> un <strong>Francija</strong>.','Collapsed' => 'Salikts','Expanded' => 'Paplašināts','Do not show' => 'Neparādiet','yes' => 'jā','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Lauciņš „Piegādes tālrunis“ var tikt iestatīts kā „obligāts“, ja rēķina adrese tiek parādīta pēc piegādes adreses un lauciņš „Rēķina tālrunis“ ir iestatīts kā „obligāts“. Tas ir nepieciešams, lai nodrošinātu, ka piegādes adrese var tikt kopēta uz rēķina adresi, ja šī opcija ir atzīmēta; pretējā gadījumā klients, iespējams, nevarēs pabeigt pasūtījuma apstiprināšanu.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Lauciņš „Rēķina tālrunis” var tikt iestatīts kā „obligāts”, ja rēķina adreses sadaļa tiek parādīta pirms piegādes adreses sadaļas un lauciņš „Piegādes tālrunis” ir iestatīts kā „obligāts”. Tas ir nepieciešams, lai nodrošinātu, ka piegādes adrese var tikt kopēta uz rēķina adresi, ja šī opcija ir atzīmēta; pretējā gadījumā klients varētu nespēt pabeigt pasūtījuma apstiprināšanu.','Settings profiles' => 'Iestatījumu profili','Settings profile' => 'Iestatījumu profils','You do not have permission to perform this action.' => 'Jums nav atļaujas veikt šo darbību.','You do not have permission to activate plugins.' => 'Jums nav atļaujas aktivizēt spraudņus.','Missing plugin.' => 'Trūkst spraudņa.','Plugin activated.' => 'Plugins ir aktivizēts.','The following changes will be applied:' => 'Tiks veikti šādi grozījumi:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Sākot ar Fluid Checkout 5.0, iestatījumi tiek saglabāti citādāk. Iepriekšējās versijas iestatījumi joprojām tiek saglabāti datu bāzē, lai vajadzības gadījumā būtu iespējams atgriezties pie iepriekšējām versijām.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Jūsu veikals jau apmēram 2 nedēļas darbojas ar jaunajiem iestatījumiem, tādēļ jūs varētu iztīrīt datu bāzē saglabātās vecās opcijas. Lūdzu, ņemiet vērā, ka pēc iztīrīšanas, ja jums būs nepieciešams atgriezties pie iepriekšējām spraudņa versijām, visiem iestatījumiem tiks izmantotas noklusējuma vērtības.','Fluid Checkout settings cleanup' => '„Fluid Checkout“ iestatījumu tīrīšana','Delete leftover options' => 'Dzēst atlikušās opcijas','Help us improve Fluid Checkout' => 'Palīdziet mums uzlabot „Fluid Checkout”','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Dalieties ar anonīmiem ziņojumiem par vietnes vidi, izmantojot „Fluid Checkout”, lai saņemtu ātrāku atbalstu un palīdzētu mums uzlabot saderību un novērtēt ietekmi. Ziņojumos netiek iekļauti ne klientu, ne lietotāju dati, ne arī konfidenciāla informācija. Jebkurā brīdī varat izvēlēties, kādu informāciju dalīties, izmantojot iestatījumus sadaļā „Rīki”.','Enable site environment reports' => 'Iespējot vietnes vides pārskatus','Review settings' => 'Pārskatīt iestatījumus','This preview has expired. Reload the admin page to start a new preview.' => 'Šī priekšskatīšana ir beigusies. Atjauniniet administratora lapu, lai sāktu jaunu priekšskatīšanu.','Preview expired' => 'Priekšskatījuma termiņš ir beidzies','Orders cannot be placed in the preview.' => 'Priekšskatījumā pasūtījumus nevar veikt.','Logging in is not available in the preview.' => 'Priekšskatījumā nav iespējams pieteikties.','Accounts cannot be created in the preview.' => 'Priekšskatījumā kontus nevar izveidot.','Requests to other sites are blocked in the preview.' => 'Priekšskatījumā tiek bloķēti pieprasījumi uz citām vietnēm.','Processing…' => 'Apstrādā…','Something went wrong. Please try again.' => 'Kaut kas nogāja greizi. Lūdzu, mēģiniet vēlreiz.','Activate plugin' => 'Aktivizēt spraudni','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO — pilnīgs kases risinājumu komplekts','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Visas PRO funkcijas + visi papildu moduļi par vienu cenu. Dizaina veidnes, optimizētas iepirkumu groza un pasūtījuma apstiprinājuma lapas, kontu saskaņošana un daudz kas cits.','Optimized order pay page' => 'Optimizēta pasūtījuma apmaksas lapa','Express checkout buttons from supported payment methods' => 'Ātrās norēķināšanās pogas atbalstītajiem maksājumu veidiem','Delayed account creation' => 'Konta izveides aizkavēšanās','Address autocomplete with Google Maps APIs' => 'Adrešu automātiskā aizpildīšana, izmantojot Google Maps API','Multiple saved addresses with the address book' => 'Vairākas saglabātas adreses adrešu grāmatā','EU-VAT assistant' => 'ES PVN palīgs','Hide this section' => 'Paslēpt šo sadaļu','Learn more' => 'Uzzināt vairāk','Get early access' => 'Iegūstiet agrīnu piekļuvi','Activate add-on' => 'Aktivizēt paplašinājumu','Get more out of your checkout journey' => 'Iegūstiet vairāk no savas pirkuma apmaksas pieredzes','Test API key' => 'API atslēgas pārbaude','Guided setup' => 'Uzstādīšana ar vadītāja palīdzību','Options' => 'Iespējas','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Iestatiet izkārtojumu un dizainu sadaļā <a href="%s">norēķināšanās opcijas</a>.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Iespējojiet norēķināšanos kā viesim un/vai pārskatiet <a href="%s">klientu kontu iestatījumus</a>.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Iespējot optimizētās <a href="%1$s">grozs</a>, <a href="%2$s">paldies</a> un <a href="%3$s">pasūtījuma apmaksa</a> lapas.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Iespējojiet <a href="%s">adrešu automātisko aizpildīšanu</a> no „Google Maps“.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Iespējojiet vairāku saglabātu adrešu izmantošanu, izmantojot <a href="%s">adrešu grāmatu</a>.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Pārbaudiet, vai šai tēmai vai citiem jūsu instalētajiem spraudņiem ir pieejamas kādas <a href="%s">integrācijas iespējas</a>.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Saņemiet ātrāku atbalstu un palīdziet mums uzlabot saderību un novērtēt ietekmi. <a href="%s">Ieslēdziet lietošanas uzraudzību</a> rīku iestatījumos.','Missing settings tab.' => 'Trūkst cilnes „Iestatījumi”.','Getting started' => 'Sākums','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Lieliski! Jūsu norēķinu lapa tagad darbojas, izmantojot Fluid Checkout.</strong> Lūk, daži soļi, lai sāktu darbu:','Completed' => 'Pabeigts','Preview report data' => 'Ziņojuma datu priekšskatīšana','Send now' => 'Nosūtīt tagad','Auto-detect' => 'Automātiskā noteikšana','Afrikaans' => 'afrikāņu valoda','Albanian' => 'albāņu','Amharic' => 'amharu valoda','Arabic' => 'arābu valoda','Armenian' => 'armēņu','Azerbaijani' => 'Azerbaidžāņu','Basque' => 'basku','Belarusian' => 'baltkrievu','Bengali' => 'bengāļu','Bosnian' => 'bosniešu','Bulgarian' => 'bulgāru','Burmese' => 'birmiešu','Catalan' => 'katalāņu','Chinese' => 'ķīniešu','Chinese (Simplified)' => 'Ķīniešu (vienkāršotā)','Chinese (Hong Kong)' => 'Ķīniešu (Honkonga)','Chinese (Traditional)' => 'Ķīniešu (tradicionālā rakstība)','Croatian' => 'horvātu','Czech' => 'Čehu','Danish' => 'dāņu','Dutch' => 'holandiešu','English' => 'angļu valoda','English (Australian)' => 'Angļu valoda (Austrālija)','English (Great Britain)' => 'Angļu valoda (Lielbritānija)','Estonian' => 'Igaunijas','Farsi' => 'farsi','Finnish' => 'somu valoda','Filipino' => 'filipīniešu','French' => 'franču','French (Canadian)' => 'Franču (kanādiešu)','Galician' => 'galisiešu','Georgian' => 'gruzīnu','German' => 'vācu','Greek' => 'grieķu','Gujarati' => 'gudžarati','Hebrew' => 'ivrits','Hindi' => 'hindi','Hungarian' => 'ungāru','Icelandic' => 'islandiešu','Indonesian' => 'indonēziešu','Italian' => 'itāļu','Japanese' => 'japāņu','Kannada' => 'Kannada','Kazakh' => 'kazahu','Khmer' => 'khmeru','Korean' => 'korejiešu','Kyrgyz' => 'Kirgīzija','Lao' => 'Laosa','Latvian' => 'latviešu','Lithuanian' => 'lietuviešu','Macedonian' => 'Maķedonijas','Malay' => 'malajiešu','Malayalam' => 'malajalamu valoda','Marathi' => 'marathi','Mongolian' => 'mongolietis','Nepali' => 'nepaliešu','Norwegian' => 'norvēģu','Polish' => 'poļu','Portuguese' => 'portugāļu valoda','Portuguese (Brazil)' => 'portugāļu (Brazīlija)','Portuguese (Portugal)' => 'portugāļu valoda (Portugāle)','Punjabi' => 'pandžabi','Romanian' => 'rumāņu','Russian' => 'krievu','Serbian' => 'serbu','Sinhalese' => 'singāļu','Slovak' => 'slovāku','Slovenian' => 'Slovēņu','Spanish' => 'spāņu valoda','Spanish (Latin America)' => 'Spāņu valoda (Latīņamerika)','Swahili' => 'suahili valoda','Swedish' => 'Zviedru','Tamil' => 'tamilu','Telugu' => 'Telugu','Thai' => 'taju valoda','Turkish' => 'turku','Ukrainian' => 'ukraiņu','Urdu' => 'Urdu','Vietnamese' => 'Vjetnamiešu','Zulu' => 'Zulu','Google address autocomplete' => '„Google“ adrešu automātiskā papildināšana','Google Places API version' => '„Google Places“ API versija','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Izvēlieties, kuru „Google Places API“ versiju izmantot. Mēs iesakām pēc iespējas drīzāk pāriet uz jauno „Places API“.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Mēs iesakām izmantot „Places API (New)”, jo no 2025. gada 1. marta Google „Places API (Legacy)” versijai piešķirs „Legacy” statusu, kas nozīmē, ka jūs vairs nevarēsiet aktivizēt šo pakalpojumu jaunām API atslēgām un ka šī API versija galu galā vairs nebūs pieejama. Esošie konti, kas jau izmanto Legacy API, var turpināt darboties bez traucējumiem.','(Recommended)' => '(Ieteicams)','Google API key' => '„Google“ API atslēga','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Ielīmējiet savu Google API atslēgu un izmantojiet pārbaudes pogu, lai pārliecinātos, ka tā darbojas šajā tīmekļa vietnē. Pārliecinieties, ka atslēga ir derīga un atļauta jūsu domēnam, citādi adreses lauks var tikt bloķēts, liedzot klientiem pabeigt pasūtījumus.','Enable Google address autocomplete' => 'Iespējot Google adrešu automātisko papildināšanu','Enable address autocompletion using the Google Maps APIs.' => 'Iespējojiet adreses automātisko aizpildīšanu, izmantojot „Google Maps“ API.','Google API language' => 'Google API valoda','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Šī valoda tiks izmantota, lai parādītu „Google Places API“ adrešu ieteikumus, un adreses tiks automātiski papildinātas arī šajā valodā.','Result types' => 'Rezultātu veidi','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Atstājiet tukšu, lai pieņemtu jebkura veida rezultātus, kas parasti nodrošina labākus saskaņošanas rezultātus. <a href="%s" target="_blank">Sīkāku informāciju skatiet dokumentācijā</a>. <br>Izvēlieties līdz 5 adreses meklēšanas rezultātu veidiem, kurus parādīt adreses automātiskās aizpildīšanas laukos. <br>Apmeklējiet Google Maps dokumentāciju, lai uzzinātu vairāk par <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">atbalstītajiem veidiem</a>.','Result types (Legacy API)' => 'Rezultātu tipi (vecā versija API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Kāda veida adrešu meklēšanas rezultātus atgriezt, izmantojot Places API (vecā versija). <br>Apskatiet Legacy Google Places API dokumentāciju, lai uzzinātu vairāk par <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">atbalstītajiem veidiem</a>.','Company fields' => 'Uzņēmuma darbības jomas','Enable autocomplete for the company name if available' => 'Ja iespējams, ieslēdziet uzņēmuma nosaukuma automātisko papildināšanu','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Iespējot uzņēmuma lauka automātisko aizpildīšanu ar uzņēmuma nosaukuma informāciju, kas tiek atgriezta no Google Maps API.','Business search' => 'Uzņēmumu meklēšana','Enable search for businesses in the company field' => 'Iespējot uzņēmumu meklēšanu uzņēmuma laukā','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Iespējot adrešu ieteikumus, kas saistīti ar uzņēmumu, kad tiek ievadīts teksts uzņēmuma laukā, un pēc tam automātiski aizpildot visus adrešu laukus, kad no ieteikumiem tiek izvēlēts uzņēmums.','Company result types' => 'Uzņēmuma rezultātu veidi','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Izvēlieties līdz 5 adreses meklēšanas rezultātu veidiem, kurus parādīt uzņēmuma lauku automātiskās aizpildīšanas funkcijā. <br>Ieteicamā vērtība ir <code>uzņēmums</code>, kas ietver lielāko daļu uzņēmumu veidu. <br>Atstājiet lauku tukšu, lai pieņemtu jebkura veida rezultātus, tostarp tos, kas nav saistīti ar uzņēmumiem. <br>Apmeklējiet „Google Maps“ dokumentāciju, lai uzzinātu vairāk par <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">atbalstītajiem veidiem</a>.','Google logo' => '„Google“ logotips','Show text and logo "Powered by Google"' => 'Rādīt tekstu un logotipu „Powered by Google“','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Ja šī izvēles rūtiņa ir atzīmēta, adreses automātiskās aizpildīšanas ieteikumu lodziņa apakšā tiks parādīts teksts un logotips „Powered by Google“.','Brasil API address autocomplete' => 'Brazīlijas API adrešu automātiskā papildināšana','Brasil API' => 'Brazīlijas API','Enable Brasil API address autocomplete for CEP fields' => 'Iespējot „Brasil API“ adrešu automātisko aizpildīšanu CEP laukos','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Izmantojiet „Brasil API“, lai iegūtu un automātiski aizpildītu adreses, izmantojot lauku „CEP/Pasta indekss“. Attiecas tikai uz Brazīlijas adresēm.','API version' => 'API versija','Choose which version of the Brasil API CEP method to use.' => 'Izvēlieties, kuru „Brasil API CEP” metodes versiju izmantot.','Address book migration' => 'Adrešu grāmatas pārnešana','WooCommerce addresses' => 'WooCommerce adreses','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Kopējiet esošās piegādes un rēķinu adreses no WooCommerce uz klientu adrešu grāmatu.','Enable the address book feature' => 'Iespējot adresātu grāmatas funkciju','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Ļaujiet klientiem saglabāt vairākas adreses un noteikt noklusējuma adresi, kas tiks izmantota sūtīšanai un rēķinu izrakstīšanai.','Address labels' => 'Adrešu uzlīmes','Allow customers to add a custom label for each address' => 'Ļaujiet klientiem katrai adresei pievienot individuālu apzīmējumu','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Adrešu etiķetes atvieglo klientiem savu saglabāto adrešu (piem., „Māmiņas māja“) atšķiršanu. Adrešu etiķetes ir konfidenciālas un netiks parādītas vai izdrukātas pasūtījuma informācijas lapā vai rēķinos.','Display layout' => 'Ekrāna izkārtojums','Choose how saved addresses are displayed at checkout and on the cart.' => 'Izvēlieties, kā saglabātās adreses tiks parādītas norēķināšanās brīdī un iepirkumu grozā.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Tiek piemērots norēķināšanās brīdī un iepirkumu grozā. Kontā saglabātās adreses vienmēr tiek attēlotas kā kartes.','Address cards' => 'Adrešu kartītes','Address list' => 'Adrešu saraksts','Dropdown field' => 'Nolaižamais izvēles lauks','Address search' => 'Adrešu meklēšana','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Rādīt adreses meklēšanas filtru lietotāja saskarnē, ja klientam ir pieejams vismaz šāds skaits saglabātu adrešu.','Not used when display layout is set to dropdown field.' => 'Netiek izmantots, ja displeja izkārtojums ir iestatīts kā nolaižamais lauks.','Addresses' => 'Adreses','Enable cart page optimizations to see more options' => 'Iespējojiet iepirkumu groza lapas optimizācijas, lai redzētu vairāk iespēju','Sticky order summary' => 'Fiksētais pasūtījuma kopsavilkums','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Izvēlieties vietu, kur groza lapā parādīt kuponu kodu sadaļu. Šī opcija ir pieejama tikai tad, ja ir ieslēgts AJAX grozs un ja WooCommerce iestatījumos ir atļauta kuponu kodu izmantošana.','Layout of cross-sell' => 'Papildu pārdošanas izkārtojums','Cross-sells displayed' => 'Parādītas papildu pārdošanas preces','Items' => 'Preces','Cart page optimization' => 'Iepirkumu groza lapas optimizācija','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Veidojiet savam iepirkumu grozam tādu pašu skaidru, uz konversiju vērstu izkārtojumu kā savai norēķinu lapai.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Saskaņojiet groza izkārtojumu ar norēķinu lapu, lai nodrošinātu vienotu pirkšanas procesu.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Nodrošiniet, lai grozs vienmēr tiktu atjaunināts fonā, un, mainoties daudzumiem, netiktu veikta pilna lapas pārlādēšana.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Ievietojiet kuponu kodus, informāciju par piegādi un papildu pārdošanas piedāvājumus tieši tur, kur tie nodrošina vislabāko konversiju.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Rūpējieties, lai pasūtījuma kopsavilkums paliktu redzams, ritinot lapu, un pievienojiet uzticamības simbolus tur, kur pircējiem nepieciešama pārliecība.','Columns' => 'Kolonnas','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Vispārējie stili norēķināšanās posmiem, pasūtījuma kopsavilkumam un citām sadaļām. Attiecas uz citām norēķināšanās, groza, pateicības (pasūtījums saņemts) un pasūtījuma apskates lapām.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Izmantojot <em>"1 kolonna"</em> izkārtojumu kopā ar <em>"Split"</em> dizaina veidni, labā kolonna tiek parādīta tikai tad, ja ir aktīva lapas sānu joslas logrīku zona („Checkout Sidebar”, „Cart Sidebar” vai „Order Received Sidebar”). Pretējā gadījumā lapa paliek vienkolonnas izkārtojumā ar „Split” stiliem.','Split column background' => 'Kolonnu fona sadalīšana','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Izvēlieties fona krāsu „Split“ dizaina otrajai slejai. Ja atstājat lauku tukšu, tiks izmantota pasūtījuma kopsavilkuma fona krāsa.','Page templates' => 'Lapu veidnes','Checkout template' => 'Norēķinu veidne','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Ieteicams, lai samazinātu uzmanības novirzes norēķinu brīdī. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Iepazīstieties ar pētījumu par iepirkumu grozu pamešanu</a>.','Sticky progress bar' => 'Fiksēta progresa josla','Progress bar style' => 'Progresa joslas stils','Order totals' => 'Pasūtījumu kopējā summa','Background color' => 'Fona krāsa','Action link' => 'Rīcības saite','Mobile order summary' => 'Mobilā pasūtījuma kopsavilkums','Mobile initial state' => 'Mobilā sākotnējā stāvoklis','Enable editing cart items at checkout' => 'Iespējot grozā esošo preču rediģēšanu norēķināšanās brīdī','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Ļaujiet klientiem mainīt preču daudzumu vai noņemt preces tieši norēķinu lapā.','Cart item errors' => 'Kļūdas preču grozā','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Tas attiecas tikai tad, ja kupona kods tiek parādīts kā atsevišķa sadaļa norēķinu vai groza lapās un ja kupona kodu izmantošana ir iespējota WooCommerce iestatījumos.','Coupon codes position' => 'Kupona kodu atrašanās vieta','Apply coupon button' => 'Poga „Piemērot kuponu“','Select style of the "apply coupon" button.' => 'Izvēlieties pogas „Piemērot kuponu” stilu.','Address line 2' => '2. adrešu rinda','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Šis iestatījums tiek izmantots gan sadaļā „Norēķināšanās”, gan sadaļā „Saņemšana klātienē”. Sadaļā „Saņemšana klātienē” tas nosaka arī to, vai izvēlne „Piegāde/Saņemšana klātienē” tiek parādīta piegādes veidu sadaļā (pirms adreses) vai kā atsevišķa sadaļa (pēc tās).','Customer accounts' => 'Klientu konti','Guest checkout' => 'Viesu norēķināšanās','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Viesu norēķināšanās, pieteikšanās un konta izveides opcijas, kas pieejamas WooCommerce kontu iestatījumu lapā. Tās tiek pārvaldītas šeit, lai jums būtu ērtāk, un lai jūs varētu izmantot atšķirīgas vērtības katram iestatījumu profilam.','Allow customers to checkout without an account' => 'Ļaujiet klientiem veikt norēķinu bez konta','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Ieteicams</strong>, lai klientiem norēķināšanās laikā netiktu prasīts izveidot kontu vai pieteikties, kas var samazināt konversijas rādītājus.','When disabled, customers must log in or create an account to complete the purchase.' => 'Ja šī funkcija ir atspējota, klientiem ir jāpiesakās vai jāizveido konts, lai pabeigtu pirkumu.','Login at checkout' => 'Piesakies, veicot norēķinu','Enable log-in during checkout' => 'Iespējot pieteikšanos norēķināšanās laikā','Show a link for returning customers to log in from the checkout page.' => 'Ievietojiet saiti, lai pastāvīgie klienti varētu pieteikties no norēķinu lapas.','Account creation' => 'Konta izveide','Allow customers to create an account during checkout' => 'Ļaujiet klientiem izveidot kontu norēķināšanās laikā','Customers can create an account before placing their order.' => 'Klienti var izveidot kontu, pirms veic pasūtījumu.','Allow customers to create an account from the My account page' => 'Ļaujiet klientiem izveidot kontu lapā „Mans konts“','Customers can register a new account from the My account page.' => 'Klienti var izveidot jaunu kontu lapā „Mans konts”.','Username' => 'Lietotājvārds','Generate from customer\'s name' => 'Izveidot, pamatojoties uz klienta vārdu','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Ieteicams</strong>, lai klientiem norēķināšanās laikā netiktu lūgts izvēlēties lietotājvārdu, kas var samazināt konversijas rādītājus.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Lietotājvārds tiek ģenerēts, izmantojot klienta vārdu vai, ja vārdu nevar izmantot, — e-pasta adresi.','Password' => 'Parole','Send password setup link' => 'Nosūtīt saiti paroles iestatīšanai','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Ieteicams</strong>, lai klientiem norēķināšanās laikā netiktu lūgts iestatīt paroli, kas var samazināt konversijas rādītājus.','Customers receive an email to create their password securely.' => 'Klienti saņem e-pastu, lai droši izveidotu savu paroli.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Ļaujiet reģistrētajiem klientiem pabeigt pasūtījuma apmaksu, neieejot sistēmā, un saistīt pasūtījumu ar viņu esošo kontu, ja kontaktinformācija sakrīt.','Existing account message' => 'Paziņojums par esošo kontu','Let customers create an account after placing their order, from the thank you page.' => 'Ļaujiet klientiem izveidot kontu pēc pasūtījuma veikšanas, izmantojot pateicības lapu.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Šajā sadaļā pieejamās opcijas ir aktīvas, ja ir ieslēgta norēķināšanās kā viesim un konta saskaņošana. Lai konfigurētu atlikto konta izveidi, ieslēdziet abas iepriekš minētās funkcijas.','Enable delayed account creation' => 'Iespējot kontu izveidi ar novilcinājumu','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Iespējot kontu izveidi ar aizkavēšanu, ja ir ieslēgta gan norēķināšanās kā viesim, gan kontu saskaņošana.','Section position' => 'Nodaļas amats','Before customer details section' => 'Pirms sadaļas „Klienta dati”','After customer details section' => 'Pēc sadaļas „Klienta dati”','Account creation benefits' => 'Priekšrocības, izveidojot kontu','Leaving the field empty will display the default text.' => 'Ja lauku atstāsiet tukšu, tiks parādīts noklusējuma teksts.','Inline buttons' => 'Iekļautās pogas','Required fields' => 'Obligātie lauki','Enable gift message fields at checkout' => 'Iespējot dāvanu ziņojumu laukus norēķināšanās brīdī','Expanded gift message' => 'Paplašināts dāvanas vēstījums','Display gift message field always expanded' => 'Lodziņš „Dāvanas vēstule” vienmēr ir atvērts','Gift message in order details' => 'Dāvanas vēstule pasūtījuma informācijā','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Šajā sadaļā pašlaik nav pieejamas integrācijas. Ar katru spraudni un tēmu saistītās opcijas šeit parādīsies tikai tad, kad šis spraudnis vai tēma tiks aktivizēta.','Phone fields' => 'Tālruņa lauki','Field visibility' => 'Lauka redzamība','Field position' => 'Pozīcija laukumā','Phone country code & validation' => 'Tālruņa valsts kods un pārbaude','Country' => 'Valsts','Enable country on phone fields' => 'Iespējot lauku „Valsts” tālruņa laukos','Filter countries for shipping or billing' => 'Filtrēt valstis pēc piegādes vai rēķina izrakstīšanas','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Ierobežojiet valstu izvēlni katrā tālruņa numura laukā, iekļaujot tikai tās valstis, uz kurām jūsu veikalā ir atļauta preču piegāde vai rēķinu izrakstīšana.','Validation' => 'Validācija','Enable simple validation based on country rules' => 'Iespējot vienkāršu pārbaudi, pamatojoties uz valstu noteikumiem','Checks that the phone number is valid for the selected country, including country code and length.' => 'Pārbauda, vai tālruņa numurs ir derīgs izvēlētajā valstī, ņemot vērā valsts kodu un ciparu skaitu.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Veikt stingrāku pārbaudi, vai numurs ir derīgs mobilais, fiksētā līnijas vai cits izvēlētajai valstij pieņemams numura veids. Var tikt noraidīti daži derīgi numuri.','Validation types' => 'Validācijas veidi','Placeholders' => 'Aizstājējzīmes','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Pašlaik nav jāpārvalda nekādas licences atslēgas. Licences atslēgas parādīsies šeit, kad būs aktivizēts licencēts „Fluid Checkout“ spraudnis vai paplašinājums.','Default delivery type' => 'Noklusējuma piegādes veids','Choose which delivery type will be selected by default.' => 'Izvēlieties, kurš piegādes veids tiks izvēlēts pēc noklusējuma.','Shipping zone fields' => 'Piegādes zonas lauki','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Izvēlieties, kuri lauki tiks parādīti kā filtra lauki vietējās preču saņemšanas piegādes zonai. Lai parādītu visas pieejamās iespējas, atstājiet laukus tukšus.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Šie lauki tiks parādīti kā filtrs vietējās preču saņemšanas piegādes veidiem. Daži lauki varētu joprojām parādīties norēķinu posmā, ja tie šeit nav atlasīti, ja to pareizai darbībai nepieciešami saderīgi spraudņi.','Order shipping address' => 'Pasūtījuma piegādes adrese','Order pay page optimization' => 'Maksājumu lapas optimizācija','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Neapmaksātajiem pasūtījumiem piešķiriet tādu pašu skaidru, uz konversiju vērstu izkārtojumu kā norēķinu lapai.','Optimize the layout of the order pay page for orders pending payment.' => 'Optimizējiet pasūtījuma apmaksas lapas izkārtojumu pasūtījumiem, par kuriem vēl nav veikta apmaksa.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Pielāgojiet pasūtījuma apmaksas procesu savai norēķinu sistēmai, lai nodrošinātu vienotu pirkšanas pieredzi.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Ievietojiet uzticamības simbolus un zīmes vietās, kur pircējiem pirms maksājuma veikšanas nepieciešama pārliecība.','Thank you page optimization' => 'Pateicības lapas optimizācija','Make the thank you page and order details clearer for customers after they buy.' => 'Padariet pateicības lapu un pasūtījuma informāciju skaidrāku klientiem pēc pirkuma veikšanas.','Optimize the thank you page and account order details with a clearer layout.' => 'Optimizējiet pateicības lapu un pasūtījuma informāciju kontā, izmantojot skaidrāku izkārtojumu.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Atbilstošajās vietās parādiet pasūtījuma statusa gaitu, darbības, lejupielādes un piezīmes.','Customize order details sections on email notifications.' => 'Pielāgojiet pasūtījuma informācijas sadaļas e-pasta paziņojumos.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Ievietojiet uzticamības simbolus un zīmes vietās, kur pircējiem pēc pirkuma ir nepieciešama pārliecība.','Email notifications' => 'Paziņojumi pa e-pastu','Enable thank you page and order details optimizations to see more options' => 'Iespējojiet pateicības lapas un pasūtījuma informācijas optimizāciju, lai redzētu vairāk iespēju','Use wide layout on thank you page' => 'Pateicības lapā izmantojiet plašu izkārtojumu','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Šīs opcijas ietekmē pateicības lapu, pasūtījuma informācijas apskati konta lapās un e-pasta paziņojumos.','Save settings' => 'Saglabāt iestatījumus','Docs' => 'Dokumenti','Cart' => 'Grozs','Thank you' => 'Paldies','Address autocomplete' => 'Adrešu automātiskā papildināšana','Trust badges' => 'Uzticamības zīmes','You do not have permission to save these settings.' => 'Jums nav atļauts saglabāt šos iestatījumus.','Invalid save request.' => 'Nepareizs saglabāšanas pieprasījums.','Your settings have been saved.' => 'Jūsu iestatījumi ir saglabāti.','Saving...' => 'Saglabāšana...','Settings could not be saved. Please try again.' => 'Iestatījumus neizdevās saglabāt. Lūdzu, mēģiniet vēlreiz.','Dismiss notice' => 'Atsaukt paziņojumu','Open settings menu' => 'Atvērt iestatījumu izvēlni','Close settings menu' => 'Aizvērt iestatījumu izvēlni','Preview' => 'Priekšskatījums','Expand preview' => 'Paplašināt priekšskatījumu','Collapse preview' => 'Aizvērt priekšskatījumu','Show header and footer' => 'Rādīt galveno un apakšējo kolonu','Hide header and footer' => 'Paslēpt galveno un apakšējo kolofonu','Page preview' => 'Lapas priekšskatījums','Preview viewport' => 'Priekšskatījuma loga skats','Tablet' => 'Planšetdators','Desktop' => 'Datoru darbvirsma','Preview width' => 'Priekšskatījuma platums','Decrease width' => 'Samazināt platumu','Preview width in pixels' => 'Priekšskatījuma platums pikseļos','Increase width' => 'Palielināt platumu','Preview as' => 'Priekšskatīt kā','Guest' => 'Viesis','Logged in' => 'Pieslēdzies','Preview page' => 'Lapas priekšskatījums','Expand preview for a closer look' => 'Paplašiniet priekšskatījumu, lai apskatītu sīkāk','Available with %s.' => 'Pieejams ar %s.','Turn them on' => 'Ieslēdziet tos','Optimizations for this page are turned off. %s to preview the page.' => 'Šīs lapas optimizācijas ir atspējotas. %s, lai apskatītu lapas priekšskatījumu.','%s preview' => '%s priekšskatījums','Isolated session · nothing is saved' => 'Atsevišķa sesija · nekas netiek saglabāts','Usage tracking' => 'Lietošanas uzraudzība','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Nosūtiet ziņojumus par vietnes vidi, kas nesatur konfidenciālu informāciju, lai palīdzētu „Fluid Checkout” uzlabot savietojamību. Ziņojumi netiks nosūtīti, kamēr šī funkcija netiks ieslēgta zemāk esošajās opcijās.','Send usage tracking reports to Fluid Checkout' => 'Nosūtiet lietošanas uzskaites pārskatus uz „Fluid Checkout“','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Šie ziņojumi palīdz mums uzlabot jūsu vietnes saderību un atbalstu, un, ja šī funkcija ir ieslēgta, tie tiek nosūtīti reizi nedēļā.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Ziņojumos nav iekļauti ne klientu, ne administratora lietotāju, ne arī citi konfidenciāli dati.','Basic environment info' => 'Pamatinformācija par vidi','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Dati par WordPress, PHP, WooCommerce, tēmām un spraudņiem. Tiek vienmēr iekļauti, ja ir ieslēgta ziņošana. Tas palīdz mums izprast vidi, kurā darbojas jūsu vietne.','Plugin settings' => 'Plugina iestatījumi','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Nosūta „Fluid Checkout“ spraudņa iestatījumus, lai atvieglotu atbalsta pieprasījumu apstrādi un palīdzētu mums izprast, kā jūs izmantojat mūsu spraudņus.','Coming soon' => 'Drīzumā','Sales metrics' => 'Pārdošanas rādītāji','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Pasūtījumu skaits mēnesī un kopējais apgrozījums vienā gadā pirms „Fluid Checkout” instalēšanas līdz šodienai. Tas palīdz mums saprast, vai jūs gūstat lielākus ienākumus, ja ir instalēti mūsu spraudņi. Nekādi klientu vai lietotāju dati netiek nosūtīti.','Utilities' => 'Komunālie pakalpojumi','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Izmantojiet <code>TomSelect</code> nolaižamo izvēlņu komponentus, nevis <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => '„TomSelect“ ir vienkāršāks izvēles saraksta komponents, kas ir mazāk pakļauts kļūdām nekā „Select2“, vienlaikus piedāvājot tādu pašu funkcionalitāti.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Nosaka, ka šī spraudņa optimizētajās lapās veidlapas lauku burtu izmērs ir 16 pikseļi, lai novērstu automātisku palielināšanu, strādājot ar veidlapas laukiem mazās ierīcēs.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Mobilajās ierīcēs pārlūkprogramma „Safari“ un citas pārlūkprogrammas var automātiski palielināt attēlu, lai teksts būtu vieglāk lasāms, ja fontu izmērs ir mazāks par 16 pikseļiem.','Enable script processing tracking on the browser console.' => 'Iespējot skriptu apstrādes izsekošanu pārlūka konsolē.','Unminified assets' => 'Neminificēti resursi','Google Maps scripts' => '„Google Maps“ skripti','Do not remove duplicate Google Maps scripts' => 'Neizdzēsiet dublētos „Google Maps“ skriptus','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Ja šī opcija ir ieslēgta, dublētie „Google Maps“ skripti netiks dzēsti, kas var izraisīt kļūdas un veiktspējas problēmas. Šo opciju izmantojiet tikai problēmu novēršanas laikā.','Widget areas' => 'Vidžetu zonas','Last step on mobile' => 'Pēdējais solis mobilajā ierīcē','Display widgets only at last step on mobile' => 'Mobilajās ierīcēs parādīt logrīkus tikai pēdējā solī','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Mobilajās ierīcēs parādīt maksājuma apstiprinājuma zīmoga logrīkus tikai tad, kad tiek skatīts pēdējais maksājuma solis','Standard' => 'Standarts','VAT number field' => 'PVN numura lauks','Add a VAT number field to the billing form.' => 'Pievienojiet rēķina veidlapai lauku PVN numuram.','Field label' => 'Lauka nosaukums','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Iestatiet PVN numura lauka nosaukumu (piem., „PVN numurs”). Daudzvalodu tīmekļa vietnēs šo lauku labāk atstāt tukšu un tulkot sākotnējo teksta virkni.','VAT Number' => 'PVN numurs','EU-VAT' => 'ES PVN','Enable the VAT number field to see more options' => 'Aktivizējiet PVN numura lauku, lai redzētu vairāk iespēju','VAT validation' => 'PVN pārbaude','Validate VAT number field for EU-VAT during checkout' => 'Pārbaudīt PVN numura lauku attiecībā uz ES PVN norēķināšanās laikā','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Pārbauda, vai norādītais PVN numurs ir derīgs PVN numurs, kas reģistrēts Eiropas VIES datu bāzē (PVN informācijas apmaiņas sistēma).','Shop VAT number' => 'Veikala PVN numurs','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Veikala PVN numurs, ko izmanto, lai pieprasītu ES PVN apstiprinājumu, un kas ir norādīts rēķinos. <br><strong>Mēs stingri iesakām pievienot jūsu veikala PVN numuru</strong>, jo pretējā gadījumā VIES pārbaudes rezultāti varētu nebūt derīgi grāmatvedības vajadzībām. <br>Piemēram: <code>ATU99999999</code> vai <code>EE999999999</code>.','Reverse charge' => 'Apgrieztā nodokļa iekasēšana','Apply reverse charge mechanism' => 'Piemērot apgrieztās nodokļu iekasēšanas mehānismu','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Ja klienta PVN numurs ir derīgs, iestatiet nodokļa likmi uz nulli un rēķinos norādiet „Apgrieztā nodokļa iekasēšana”. Atkarībā no veikala atrašanās valsts var būt nepieciešams cits teksts „Apgrieztā nodokļa iekasēšana”.','Same country' => 'Tā pati valsts','Apply reverse charge mechanism for transactions in the shop country:' => 'Piemērot apgrieztās nodokļu iekasēšanas mehānismu darījumiem veikala atrašanās valstī:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Ļauj piemērot apgrieztās nodokļu iekasēšanas mehānismu darījumiem starp uzņēmumiem, kas atrodas tajā pašā valstī, kurā atrodas veikals.','Reverse charge exceptions' => 'Izņēmumi attiecībā uz apgrieztās nodokļu iekasēšanas kārtību','Select additional countries to skip applying the reverse charge mechanism.' => 'Izvēlieties citas valstis, kurās nepiemēros apgrieztās nodokļu iekasēšanas mehānismu.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Pasūtījumiem no šīm valstīm tiks piemēroti nodokļi pat tad, ja ir norādīts derīgs PVN numurs.','Reverse charge label on invoices' => 'Rēķinu marķējums par apgrieztās nodokļu iekasēšanas kārtību','Set the label of "reverse charge" on the checkout page and order details.' => 'Norādiet apzīmējumu „apgrieztā nodokļu iekasēšana” norēķinu lapā un pasūtījuma informācijā.','Reverse charge text on invoices' => 'Teksts par apgrieztās nodokļu iekasēšanas kārtību rēķinos','Set the label of "reverse charge" text on invoices.' => 'Rēķinos norādiet tekstu „apgrieztā nodokļa iekasēšana”.','Tax to be paid on reverse charge basis' => 'Nodoklis, kas jāmaksā saskaņā ar apgrieztās nodokļu iekasēšanas principu','Company name' => 'Uzņēmuma nosaukums','Autocomplete company name from VAT number' => 'Uzņēmuma nosaukuma automātiska aizpildīšana pēc PVN numura','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Ierakstiet rēķina izrakstītāja uzņēmuma nosaukumu, pamatojoties uz klienta norādīto derīgo PVN numuru.','Company name editing' => 'Uzņēmuma nosaukuma rediģēšana','Allow editing of auto-filled company name' => 'Atļaut rediģēt automātiski aizpildīto uzņēmuma nosaukumu','When enabled, customers can change the company name associated with the provided VAT number.' => 'Ja šī funkcija ir ieslēgta, klienti var mainīt uzņēmuma nosaukumu, kas saistīts ar norādīto PVN numuru.','EU-VAT for digital goods' => 'ES PVN digitālajām precēm','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'No 2015. gada 1. janvāra ir veiktas izmaiņas ES PVN noteikumos attiecībā uz digitālajām precēm, kas skar vienīgi B2C darījumus. PVN par digitālajām precēm jāaprēķina, pamatojoties uz klienta atrašanās vietu, un par to ir jāiegūst pierādījumi (IP adrese un rēķina adrese).','Tax classes for digital goods' => 'Digitālo preču nodokļu klases','Select some tax classes' => 'Izvēlieties dažas nodokļu klases','Location evidence' => 'Pierādījumi par atrašanās vietu','Collect customer\'s location evidence' => 'Vāciet pierādījumus par klienta atrašanās vietu','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Saglabā IP adresi un salīdzina to ar klienta rēķina adresi. Ja klienta rēķina adrese un IP adrese norāda uz atšķirīgām valstīm, klientam ir jāapstiprina sava rēķina adrese, atzīmējot izvēles rūtiņu norēķinu lapā.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Šo opciju var pārvaldīt Fluid Checkout. <a href="%s">To var mainīt sadaļā „Klientu kontu iestatījumi”</a>.','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Šo iestatījumu var pārvaldīt sadaļā „Fluid Checkout“. To var mainīt sadaļā „Fluid Checkout“ > „Klientu konti“.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Šo opciju pārvalda Fluid Checkout. Ja Fluid Checkout ir aktivizēts, piegādes galamērķis vienmēr tiek iestatīts uz „Noklusējuma vērtība — klienta piegādes adrese”. Klienti joprojām var norādīt atšķirīgas piegādes un rēķina adreses norēķināšanās laikā.<br><br>Iespēja iestatīt, lai noklusējuma rēķina adrese būtu tāda pati kā piegādes adrese, ir pieejama <a href="%s">„Fluid Checkout“ iestatījumos</a>.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Šo opciju pārvalda Fluid Checkout. Kad ir aktivizēts „Fluid Checkout”, piegādes galamērķis vienmēr tiek iestatīts uz „Pēc noklusējuma — klienta piegādes adrese”. Klienti joprojām var norādīt atšķirīgas piegādes un rēķina adreses norēķināšanās laikā.<br><br>Iespēja iestatīt, lai noklusējuma rēķina adrese būtu tāda pati kā piegādes adrese, ir pieejama sadaļā „WooCommerce” > „Iestatījumi” > „Fluid Checkout”.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Šie iestatījumi ir pārvietoti uz WP Admin > Fluid Checkout > Iestatījumi.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Šī WooCommerce iestatījumu cilne vairs netiek atbalstīta un tiks noņemta versijā „Fluid Checkout 6.0”.','Go to settings page' => 'Pāriet uz iestatījumu lapu','Hide this tab permanently' => 'Pastāvīgi paslēpt šo cilni','Site report preview' => 'Vietnes pārskata priekšskatījums','This is the data that would be included in the next site environment report based on your current settings.' => 'Šie ir dati, kas, ņemot vērā jūsu pašreizējos iestatījumus, tiktu iekļauti nākamajā vietnes vides pārskatā.','Loading report preview...' => 'Tiek ielādēts ziņojuma priekšskatījums...','Could not load the site report preview. Try again.' => 'Neizdevās ielādēt vietnes pārskata priekšskatījumu. Mēģiniet vēlreiz.','Could not send the site report. Try again.' => 'Neizdevās nosūtīt vietnes ziņojumu. Mēģiniet vēlreiz.','Site report sent successfully.' => 'Vietnes ziņojums veiksmīgi nosūtīts.','Enable and send now' => 'Aktivizēt un nosūtīt tagad','Close' => 'Aizvērt','A site report request is already in progress. Try again in a moment.' => 'Jau tiek apstrādāts pieprasījums par objekta pārskatu. Lūdzu, mēģiniet vēlreiz pēc brīža.','Site environment reporting is disabled.' => 'Ziņošana par vietnes vidi ir atspējota.','No site report data is available to send.' => 'Nav pieejami nekādi vietas pārskata dati, kurus varētu nosūtīt.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Šī vietnes domēna nevar nosūtīt vides pārskatus (izņemot vietējos vai izstrādes domēnus).','A site report was sent recently. Try again later.' => 'Nesen tika nosūtīts objekta ziņojums. Lūdzu, mēģiniet vēlāk.','The site report could not be sent. Try again later.' => 'Vietnes ziņojumu neizdevās nosūtīt. Mēģiniet vēlāk.','Site environment reporting is not available.' => 'Ziņojumi par objekta apkārtējo vidi nav pieejami.','No site report data is available for the selected settings.' => 'Par izvēlētajiem iestatījumiem nav pieejami dati no vietnes pārskata.','You are not allowed to manage site reports.' => 'Jums nav atļauts pārvaldīt vietnes pārskatus.','PRO feature' => 'PRO funkcija','Other plugins' => 'Citi spraudņi','Get only this add-on &mdash; %s' => 'Iegādājieties tikai šo papildu moduli — %s','Install add-on' => 'Instalēt paplašinājumu','Upgrade to PRO &mdash; %s' => 'Pārejiet uz PRO versiju — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Iegādājieties %2$s</a>, lai atbloķētu šīs iespējas.','Add-on' => 'Papildinājums','View documentation' => 'Apskatīt dokumentāciju','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Lūgumiem ir nepieciešams pieteicies WordPress lietotājs. Izlaidiet user_id, lai izmantotu pašreizējā lietotāja datus, vai norādiet user_id, lai vērstos pie cita konta, ja izsaucējam ir tiesības rediģēt šo lietotāju (edit_user tiesības). Neautentificēti lūgumi atgriež fc_api_forbidden. Ja user_id ir nederīgs, tiek atgriezts kļūdas kods fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 ar { "data": { ... } }, ja apstrādātājs atgriež datu slodzi.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 ar { "success": true }, ja nav datu (piemēram, DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Kļūdas atgriež WordPress REST kļūdas JSON no WP_Error (kods, ziņojums, data.status). Wire kodi izmanto prefiksu fc_api_*.','Forbidden access.' => 'Piekļuve aizliegta.','Target user was not found.' => 'Mērķa lietotājs netika atrasts.','This feature is not available.' => 'Šī funkcija nav pieejama.','A required address field is missing.' => 'Trūkst obligātā adreses lauka.','Postcode or ZIP is invalid.' => 'Pasta indekss vai ZIP kods ir nepareizs.','Phone number is invalid.' => 'Tālruņa numurs ir nepareizs.','State or county is invalid.' => 'Norādītā pavalsts vai apgabals nav derīgs.','Country is invalid or has no address fields.' => 'Valsts nav derīga vai tajā nav adreses lauku.','The request could not be processed.' => 'Pieprasījumu neizdevās apstrādāt.','Back to previous step' => 'Atgriezties pie iepriekšējā soļa','Skip to settings' => 'Pāriet uz iestatījumiem','Start over and return to the first guided setup step' => 'Sāciet no jauna un atgriezieties pie pirmā vadītās uzstādīšanas soļa','Start over' => 'Sākt no jauna','Please complete all sub-steps before continuing.' => 'Lūdzu, veiciet visus apakšsoļus, pirms turpināt.','Expand' => 'Paplašināt','Collapse' => 'Saslēgt','Skip' => 'Pāriet tālāk','Mark as complete' => 'Atzīmēt kā pabeigtu','Mark as incomplete' => 'Atzīmēt kā nepabeigtu','View full-size image: %s' => 'Skatīt attēlu pilnā izmērā: %s','Full-size setup guide image' => 'Pilna izmēra uzstādīšanas rokasgrāmatas attēls','Close image' => 'Aizvērt attēlu','Fluid Checkout Guided Setup' => '„Fluid Checkout“ vadītā uzstādīšana','Welcome' => 'Laipni lūdzam!','Explore your checkout' => 'Iepazīstieties ar norēķinu procesu','All set' => 'Viss ir gatavs','You do not have permission to access this page.' => 'Jums nav atļaujas piekļūt šai lapai.','Go to step %1$d: %2$s' => 'Pāriet uz %1$d. soli: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Šī vadītā uzstādīšana palīdzēs jums iepazīties ar „Fluid Checkout”. Turpmāk minētie soļi pagaidām ir tikai vietas aizpildītāji.','Continue to the next step when you are ready.' => 'Kad būsiet gatavs, turpiniet ar nākamo soli.','Open your store checkout to see Fluid Checkout in action.' => 'Atveriet savas veikala norēķinu lapu, lai redzētu, kā darbojas „Fluid Checkout“.','View checkout page' => 'Apskatīt norēķinu lapu','You can return to Fluid Checkout settings to continue configuring your store.' => 'Jūs varat atgriezties pie „Fluid Checkout“ iestatījumiem, lai turpinātu savas veikala konfigurēšanu.','Review checkout and cart settings' => 'Pārskatiet norēķināšanās un iepirkumu groza iestatījumus','Explore add-ons from the dashboard' => 'Iepazīstieties ar papildu funkcijām vadības panelī','Finish & go to settings' => 'Pabeigt un pāriet uz iestatījumiem','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Atjauniniet rēķina tālruņa lauka redzamības iestatījumu, mainot iepriekšējo vērtību, lai tā atbilstu WooCommerce standartiem.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Atjauniniet sūtīšanas tālruņa lauka redzamības iestatījumu, mainot iepriekšējo vērtību, lai tā atbilstu WooCommerce standartiem.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Kopējiet pasūtījuma kopsavilkuma fona krāsas iestatījumu uz jauno „Split” dizaina sekundārās kolonnas fona krāsas opciju.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Izmantojot „Biteship“ spraudni, paplašinātā lauku atlases funkcija vienmēr ir atspējota.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Izmantojot „German Market“, pasūtījuma izvietošanas pozīcija vienmēr tiek iestatīta uz „Zem pasūtījuma kopsavilkuma“. Šim spraudnim ir nepieciešams, lai pasūtījuma izvietošanas poga un juridiskās atzīmes tiktu parādītas zem pasūtījuma kopsavilkuma.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Izmantojot spraudni „Germanized for WooCommerce“, pasūtījuma veikšanas pozīcija vienmēr tiek iestatīta uz „Zem pasūtījuma kopsavilkuma“. Šis spraudnis prasa, lai pasūtījuma veikšanas poga un juridiskās atzīmes tiktu parādītas zem pasūtījuma kopsavilkuma.','Edit pickup locations' => 'Rediģēt preču saņemšanas vietas','Use local pickup label from WooCommerce settings' => 'Izmanto vietējās saņemšanas etiķeti no WooCommerce iestatījumiem','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Ja šī funkcija ir ieslēgta, pasūtījuma apmaksas posmā redzamais saņemšanas opcijas nosaukums atbilst nosaukumam, kas norādīts WooCommerce saņemšanas vietas iestatījumos. Ja šī funkcija ir izslēgta, nosaukumā tiek izmantots tulkojams teksts „Saņemšana uz vietas” no Fluid Checkout.','Button label for applying coupon codesApply' => 'Piesakies','Checkout step titleContact' => 'Sazinieties ar','Checkout step titleShipping' => 'Piegāde','Checkout step titleBilling' => 'Rēķini','Checkout step titlePayment' => 'Maksājums','Checkout substep change link labelChange' => 'Mainīt','Checkout substep save link labelSave changes' => 'Izmaiņu saglabāšana','Substep review textNone.' => 'Nav.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Nav atlasīts neviens attēls.','Settings sectionCart' => 'Grozs','Settings sectionOrder pay' => 'Pasūtījuma apmaksa','Settings sectionThank you' => 'Paldies','Settings section titleIntegrations' => 'Integrācija','Settings section titleLicense keys' => 'Licences atslēgas','Captcha positionBefore place order section' => 'Pirms veikt pasūtījumu sadaļā','Captcha positionBefore place order button' => 'Pirms vietas pasūtījuma pogas','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Aizvērt','Log in link label at checkout contact stepLog in' => 'Piesakieties','Log in separator label at for when guest checkout is disabledOr continue below' => 'Vai turpiniet tālāk','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Vai turpināt kā viesis','Clear image selection on admin pages.Remove image' => 'Noņemt attēlu','shipping packagesShipping %d' => 'Piegāde %d','shipping packagesShipping' => 'Piegāde','Used as fallback for "Proceed to next step" button labelnext step' => 'nākamais solis','Substep review checkbox valueYes' => 'Jā','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'Džons','Dummy customer last name in the admin previewDoe' => 'Doe','Dummy customer company in the admin previewExample Company' => 'Piemēra uzņēmums','Dummy customer street address in the admin preview123 Main Street' => '123 Galvenā iela','Dummy customer city in the admin previewAnytown' => 'Jebkura pilsēta','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Lūdzu, atstājiet sūtījumu pie ieejas durvīm.','Dummy product name in the admin previewBeanie' => 'Cepure','Dummy product name in the admin previewCap' => 'Vāciņš','Dummy product name in the admin previewT-Shirt' => 'T-krekls','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Mēs esam saņēmuši jūsu pasūtījumu un nosūtīsim jums paziņojumu, kad tas tiks nosūtīts.','Dummy download in the admin previewUser guide' => 'Lietotāja rokasgrāmata','Google Places API versionsPlaces API (New)' => 'Vietu API (jauns)','Google Places API versionsPlaces API (Legacy)' => 'Vietu API (vecā versija)','Brasil API versionsVersion 1' => '1. versija','Brasil API versionsVersion 2' => '2. versija','Delayed account creation benefits placeholder text✔ Checkout faster next time
